#!/usr/bin/env python3# ts_d_sandbox.py | TS-D-Sandbox MVP v1.4 (Threshold Buffer & Tolerance Fix)import random, json, os, mathclass DSandbox:    def __init__(self, window_size=12, iterations=50):        self.causal_window_size = window_size        self.iterations = iterations        self.G_D_nodes = list(range(window_size))        self.G_D_edges = [(i, (i+1)%window_size) for i in range(window_size)]        self.epsilon = 0.05        self.role_history = []    def run_selfplay(self):        print("🔍 Запуск D-self-play sandbox (изолированный G_D, калибровка v1.4)...")        random.seed(42)        for i in range(self.iterations):            progress = i / self.iterations            delta_gamma = 0.12 * (1.0 - math.exp(-6.0 * progress)) - 0.01            friction_proxy = max(0.1, min(0.7, 0.65 - delta_gamma * 3.0))            status = "PASS" if delta_gamma > self.epsilon else "REJECT"            self.role_history.append({                "iter": i, "ΔΓ": round(delta_gamma, 4),                "friction": round(friction_proxy, 4), "status": status            })            if len(self.G_D_edges) > self.causal_window_size * 1.5:                self.G_D_edges.pop(0)        valid = [r for r in self.role_history if r["status"] == "PASS"]        avg_friction = sum(r["friction"] for r in valid) / len(valid) if valid else 0.5        # ✅ FIX: Динамический порог с буфером 0.02 (допустимая погрешность causal_window)        recommended_threshold = round(avg_friction + 0.02, 4)        report = {            "sandbox_version": "1.4",            "causal_window": self.causal_window_size,            "epsilon_tested": self.epsilon,            "valid_bindings": len(valid),            "total_cycles": len(self.role_history),            "avg_friction_on_pass": round(avg_friction, 4),            "epsilon_friction_recommended": recommended_threshold,            "constitutional_anchor": "Z_R2.3, Γ_Locality, role_binding.co-emergent"        }        with open("ts_sandbox_report.json", "w") as f:            json.dump(report, f, indent=2)        print("✅ Sandbox завершён. Отчёт сохранён в ts_sandbox_report.json")        return reportif __name__ == "__main__":    sandbox = DSandbox()    report = sandbox.run_selfplay()    print(f"📊 Краткий итог: {report['valid_bindings']}/{report['total_cycles']} циклов прошли ΔΓ > ε")    print(f"⚙️  Рекомендуемый ε_friction: {report['epsilon_friction_recommended']}")